public sealed class OrderFunctions(IOrderProcessor processor, ILogger<OrderFunctions> log)
{
    // Runs for every message on the 'orders' queue (at-least-once delivery)
    [Function("ProcessOrder")]
    public async Task ProcessOrder(
        [ServiceBusTrigger("orders", Connection = "ServiceBus")] OrderCreated message,
        CancellationToken ct)
    {
        log.LogInformation("Processing order {OrderId}", message.OrderId);
        await processor.HandleAsync(message, ct);             // must be idempotent
    }

    // Nightly cleanup at 02:00 UTC
    [Function("NightlyCleanup")]
    public Task Cleanup([TimerTrigger("0 0 2 * * *")] TimerInfo timer)
        => processor.PurgeExpiredAsync();
}

