using Azure.Identity;
using Azure.Security.KeyVault.Secrets;

var builder = WebApplication.CreateBuilder(args);

var vaultUri = new Uri(builder.Configuration["KeyVault:Uri"]!); // https://myvault.vault.azure.net/

// Managed identity in Azure, Azure CLI / VS login locally
var credential = builder.Environment.IsDevelopment()
    ? new DefaultAzureCredential()
    : (Azure.Core.TokenCredential)new ManagedIdentityCredential(ManagedIdentityId.SystemAssigned);

// Secrets become configuration: "ConnectionStrings--Db" -> ConnectionStrings:Db
builder.Configuration.AddAzureKeyVault(vaultUri, credential, new AzureKeyVaultConfigurationOptions
{
    ReloadInterval = TimeSpan.FromMinutes(30)   // pick up rotated secrets
});

// Direct access for on-demand secrets (singleton, thread-safe)
builder.Services.AddSingleton(new SecretClient(vaultUri, credential));

var app = builder.Build();

app.MapGet("/health/secrets", async (SecretClient client) =>
{
    KeyVaultSecret secret = await client.GetSecretAsync("PartnerApiKey");
    return Results.Ok(new { secret.Name, secret.Properties.Version }); // never return the value
});

app.Run();

