    "mybus.servicebus.windows.net", new DefaultAzureCredential());  // register as singleton in DI

// --- Publish (topic -> many subscriptions) ---
ServiceBusSender sender = client.CreateSender("order-events");
var msg = new ServiceBusMessage(BinaryData.FromObjectAsJson(new { OrderId = 42, Total = 99.5m }))
{
    MessageId = "order-42-created",       // enables duplicate detection
    SessionId = "customer-7",             // FIFO per customer (session-enabled entity)
    Subject = "OrderCreated",
    ContentType = "application/json"
};
msg.ApplicationProperties["region"] = "EU"; // used by subscription SQL filters
await sender.SendMessageAsync(msg);

// --- Consume (Peek-Lock) ---
ServiceBusSessionProcessor processor = client.CreateSessionProcessor("order-events", "billing",
    new ServiceBusSessionProcessorOptions
    {
        AutoCompleteMessages = false,
        MaxConcurrentSessions = 8,
        MaxAutoLockRenewalDuration = TimeSpan.FromMinutes(5)
    });

processor.ProcessMessageAsync += async args =>
{
    var order = args.Message.Body.ToObjectFromJson<OrderCreated>();
    await billing.ChargeAsync(order);                    // idempotent handler
    await args.CompleteMessageAsync(args.Message);       // remove from queue
};
processor.ProcessErrorAsync += args =>
{
    logger.LogError(args.Exception, "Service Bus error on {Entity}", args.EntityPath);
    return Task.CompletedTask;                           // after MaxDeliveryCount -> DLQ
};
await processor.StartProcessingAsync();

