// dotnet add package Azure.Identity
builder.Services.AddSingleton(new BlobServiceClient(
    new Uri("https://mystorage.blob.core.windows.net"), new DefaultAzureCredential()));

// 1) Upload through the API - streamed, never buffered in memory
app.MapPost("/files", async (IFormFile file, BlobServiceClient svc) =>
{
    var container = svc.GetBlobContainerClient("uploads");
    var blob = container.GetBlobClient($"{Guid.NewGuid()}{Path.GetExtension(file.FileName)}");

    await using var stream = file.OpenReadStream();
    await blob.UploadAsync(stream, new BlobUploadOptions
    {
        HttpHeaders = new BlobHttpHeaders { ContentType = file.ContentType },
        Conditions = new BlobRequestConditions { IfNoneMatch = ETag.All }, // never overwrite
        TransferOptions = new StorageTransferOptions { MaximumConcurrency = 4 }
    });
    return Results.Created(blob.Uri, new { blob.Name });
}).DisableAntiforgery();

// 2) Valet key: short-lived user delegation SAS for direct browser upload
app.MapGet("/files/upload-url", async (BlobServiceClient svc) =>
{
    var expires = DateTimeOffset.UtcNow.AddMinutes(10);
    UserDelegationKey key = await svc.GetUserDelegationKeyAsync(DateTimeOffset.UtcNow, expires);

    var blob = svc.GetBlobContainerClient("uploads").GetBlobClient($"{Guid.NewGuid()}.bin");
    var sas = new BlobSasBuilder(BlobSasPermissions.Create | BlobSasPermissions.Write, expires)
    {
        BlobContainerName = blob.BlobContainerName,
        BlobName = blob.Name,
        Protocol = SasProtocol.Https
    };
    var uri = new BlobUriBuilder(blob.Uri)
    {
        Sas = sas.ToSasQueryParameters(key, svc.AccountName)
    }.ToUri();
    return Results.Ok(new { uploadUrl = uri, expires });
});
